SELECT homepage_id, manage_code, reserve_config_idx, day_of_week, reserve_start_time, reserve_end_time, use_yn, take_term, expire_date_cnt, add_id, add_date, modify_id, modify_date, tomorrow_end_day_yn FROM NEIGHBORHOOD_LIBRARY_RESERVE_CONFIG
WHERE manage_code = #{manage_code}
ORDER BY day_of_week

SELECT homepage_id, manage_code, reserve_config_idx, day_of_week, reserve_start_time, reserve_end_time, use_yn, take_term, expire_date_cnt, add_id, add_date, modify_id, modify_date, tomorrow_end_day_yn FROM NEIGHBORHOOD_LIBRARY_RESERVE_CONFIG
WHERE manage_code = #{manage_code}
ORDER BY day_of_week

SELECT count(*) FROM NEIGHBORHOOD_LIBRARY_RESERVE_CONFIG WHERE TO_CHAR(SYSDATE, 'D') = day_of_week
AND manage_code = #{manage_code}
AND SYSDATE BETWEEN TO_DATE(TO_CHAR(SYSDATE, 'yyyyMMdd') || #{reserve_start_time}, 'yyyyMMddHH24mi') AND TO_DATE(TO_CHAR(SYSDATE, 'yyyyMMdd') || #{reserve_end_time}, 'yyyyMMddHH24mi')
